96:   const inputs = bg.kind === "gif"
97:     ? ["-stream_loop", "-1", "-i", "bg.gif"]
98:     : ["-f", "lavfi", "-i", `gradients=s=1280x720:c0=${bg.colors[0]}:c1=${bg.colors[1]}:speed=0.01:rate=30:duration=${seconds}`];
99: 
100:   const bgLabel = style === "lofi" ? "bg" : "bg0";
101:   const chain = [
102:     `[0:v]scale=1280:720:force_original_aspect_ratio=increase,crop=1280:720,setsar=1,fps=30[${bgLabel}]`,
103:     "[1:a]showwaves=s=1280x180:mode=cline:colors=0xffffff:rate=30[w]",
104:     "[bg][w]overlay=0:500:format=auto[v0]",
105:   ];
106:   if (style !== "lofi") chain.splice(1, 0, STYLE_FILTERS[style]);
107:   let last = "v0";
108:   const texts = [];
109:   if (title) texts.push({ file: "title.txt", text: title.slice(0, 60), size: 54, color: "white", y: "170", x: "(w-text_w)/2" });
110:   if (sub) texts.push({ file: "sub.txt", text: sub, size: 26, color: "white@0.7", y: "245", x: "(w-text_w)/2" });
111:   if (watermark) texts.push({ file: "wm.txt", text: watermark.slice(0, 60), size: 24, color: "white@0.5", y: "h-text_h-20", x: "w-text_w-20" });
112:   texts.push(...timed);
113:   for (const [i, t] of texts.entries()) {
114:     await writeFile(path.join(jobDir, t.file), t.text);
115:     const enable = t.enable ? `:enable='${t.enable}'` : "";
116:     chain.push(`[${last}]drawtext=fontfile=font.ttf:textfile=${t.file}:fontcolor=${t.color}:fontsize=${t.size}:x=${t.x}:y=${t.y}${enable}[t${i}]`);
117:     last = `t${i}`;
118:   }
119:   chain.push(`[${last}]format=yuv420p[v]`);
120: 
121:   const args = [
122:     "-y", "-hide_banner", "-loglevel", "error",
123:     ...inputs,
124:     "-i", "audio.wav",
125:     "-filter_complex", chain.join(";"),
126:     "-map", "[v]", "-map", "1:a",
127:     "-t", String(seconds),
128:     "-c:v", "libx264", "-preset", "veryfast", "-crf", "23",
129:     "-c:a", "aac", "-b:a", "192k",
130:     "-movflags", "+faststart",
131:     "out.mp4",
132:   ];
133:   await runProcess(FFMPEG, args, jobDir);
