166: async function generateSlides({ scenes, seconds, watermark }) {
167:   const lines = scenes.split("\n").map((s) => s.trim()).filter(Boolean).slice(0, 12);
168:   if (!lines.length) throw new Error("Add at least one scene line");
169:   const mood = pickMood(lines.join(" "));
170:   const m = MOODS[mood];
171:   const { id, jobDir } = await newJob();
172:   renderWav(path.join(jobDir, "audio.wav"), { mood, seconds, seed: lines.join("|") + id });
173:   const step = seconds / lines.length;
174:   const timed = lines.map((line, i) => ({
175:     file: `scene${i}.txt`,
176:     text: line.slice(0, 60),
177:     size: 36,
178:     color: "white",
179:     x: "(w-text_w)/2",
180:     y: "(h-text_h)/2",
181:     enable: `between(t,${(i * step).toFixed(2)},${((i + 1) * step).toFixed(2)})`,
182:   }));
183:   await renderMp4(jobDir, { seconds, bg: { kind: "gradient", colors: m.colors }, title: null, sub: null, watermark: watermark || "", timed });
184:   return { id, label: `${lines.length} scene${lines.length > 1 ? "s" : ""}` };
185: }
