187: async function trimSilence(jobId) {
188:   const srcDir = path.join(OUT, jobId);
189:   const src = path.join(srcDir, "out.mp4");
190:   const log = await runProcess(
191:     FFMPEG,
192:     ["-hide_banner", "-nostats", "-i", src, "-vn", "-af", "silencedetect=noise=-35dB:d=0.6", "-f", "null", "-"],
193:     srcDir,
194:   );
195:   const dm = /Duration: (\d+):(\d+):([\d.]+)/.exec(log);
196:   if (!dm) throw new Error("Could not read video duration");
197:   const total = Number(dm[1]) * 3600 + Number(dm[2]) * 60 + Number(dm[3]);
198:   const starts = [...log.matchAll(/silence_start: ([\d.]+)/g)].map((m) => Number(m[1]));
199:   const ends = [...log.matchAll(/silence_end: ([\d.]+)/g)].map((m) => Number(m[1]));
200:   const PAD = 0.15;
201:   const keep = [];
202:   let cursor = 0;
203:   starts.forEach((s, i) => {
204:     const e = ends[i] ?? total;
205:     if (s > cursor) keep.push([cursor, Math.min(total, s + PAD)]);
206:     cursor = Math.max(cursor, e - PAD);
207:   });
208:   if (cursor < total) keep.push([cursor, total]);
209:   const segs = keep.filter(([a, b]) => b - a > 0.1);
210:   const keptTotal = segs.reduce((n, [a, b]) => n + b - a, 0);
211:   if (!segs.length || total - keptTotal < 0.5) throw new Error("Nothing to trim: no long pauses found");
212:   if (segs.length > 300) throw new Error("Too many pauses to trim");
213: 
214:   const expr = segs.map(([a, b]) => `between(t,${a.toFixed(3)},${b.toFixed(3)})`).join("+");
215:   const { id, jobDir } = await newJob();
216:   await runProcess(
217:     FFMPEG,
218:     [
219:       "-y", "-hide_banner", "-loglevel", "error",
220:       "-i", src,
221:       "-filter_complex", `[0:v]select='${expr}',setpts=N/FRAME_RATE/TB[v];[0:a]aselect='${expr}',asetpts=N/SR/TB[a]`,
222:       "-map", "[v]", "-map", "[a]",
223:       "-c:v", "libx264", "-preset", "veryfast", "-crf", "23",
224:       "-c:a", "aac", "-b:a", "192k",
225:       "-movflags", "+faststart",
226:       "out.mp4",
227:     ],
228:     jobDir,
229:   );
230:   return { id, removedSeconds: total - keptTotal };
231: }
