  morning: {
    label: "Slow morning",
    bpm: 76,
    progression: ["Fmaj7", "Em7", "Dm7", "G7"],
    colors: ["0x3b4a3f", "0xe8c9a0"],
  },
};

export function pickMood(prompt) {
  const p = prompt.toLowerCase();
  if (/sunset|golden|warm|autumn|orange|dusk/.test(p)) return "sunset";
  if (/morning|coffee|sun|cozy|breakfast|dawn/.test(p)) return "morning";
  return "night";
}

function seededRandom(seedStr) {
  let h = 2166136261;
  for (const ch of seedStr) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  if (h === 0) h = 1;
  return () => {
    h ^= h << 13;
    h ^= h >>> 17;
    h ^= h << 5;
    return (h >>> 0) / 4294967296;
  };
}

function synthesize(mood, seconds, seed) {
  const m = MOODS[mood];
  const rand = seededRandom(seed);
  const total = Math.floor(seconds * SAMPLE_RATE);
  const out = new Float32Array(total);
  const chordLen = (4 * 60) / m.bpm;
  const wowRate = 0.12 + rand() * 0.08;
  let lp = 0;

  for (let c = 0; ; c++) {
    const start = c * chordLen;
    if (start >= seconds) break;
    const freqs = CHORDS[m.progression[c % m.progression.length]];
    const i0 = Math.floor(start * SAMPLE_RATE);
    const i1 = Math.min(total, Math.floor((start + chordLen + 0.5) * SAMPLE_RATE));
    for (let i = i0; i < i1; i++) {
      const t = i / SAMPLE_RATE;
      const local = t - start;
      const env = Math.min(1, local / 0.35) * (local > chordLen ? Math.exp(-(local - chordLen) * 4) : 1);
      const wow = 1 + 0.0015 * Math.sin(2 * Math.PI * wowRate * t);
      let note = 0;
      for (const f of freqs) {
        const phase = 2 * Math.PI * f * wow * t;
        note += Math.sin(phase) + 0.25 * Math.sin(2 * phase);
      }
      const trem = 0.85 + 0.15 * Math.sin(2 * Math.PI * 0.9 * t);
      out[i] += env * trem * note * 0.05;
    }
  }

  for (let i = 0; i < total; i++) {
    let x = out[i] + (rand() * 2 - 1) * 0.01;
    if (rand() < 0.00004) x += (rand() * 2 - 1) * 0.3;
    lp += 0.3 * (x - lp);
    out[i] = lp;
