* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  background: var(--bg);
  background-image: var(--bg-gradient);
  background-attachment: fixed;
  color: var(--text);
  font-family: "Outfit", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* Subtle Retro Audio Grid Background */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background-size: 32px 32px;
  background-image: 
    linear-gradient(to right, rgba(255, 255, 255, 0.015) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.015) 1px, transparent 1px);
  pointer-events: none;
  z-index: 0;
}

h1, h2, h3, h4 {
  margin: 0;
  font-weight: 600;
  letter-spacing: -0.02em;
}

p {
  margin: 0;
}

/* Glass Header */
.topbar {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem clamp(1rem, 4vw, 2.5rem);
  background: color-mix(in srgb, var(--surface) 80%, transparent);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.brand-icon {
  width: 2.2rem;
  height: 2.2rem;
  border-radius: 10px;
  background: linear-gradient(135deg, #f59e0b, #f43f5e);
  display: grid;
  place-items: center;
  color: #fff;
  box-shadow: 0 0 16px var(--accent-glow);
  position: relative;
  overflow: hidden;
}

.brand-badge {
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 0.15rem 0.5rem;
  border-radius: 100px;
  background: rgba(245, 158, 11, 0.15);
  color: var(--accent);
  border: 1px solid rgba(245, 158, 11, 0.3);
  font-weight: 600;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* Main Studio Layout */
.studio-container {
  position: relative;
  z-index: 1;
  max-width: 1440px;
  margin: 0 auto;
  padding: clamp(1rem, 3vw, 2rem);
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
  gap: 1.8rem;
}

@media (max-width: 1024px) {
  .studio-container {
    grid-template-columns: 1fr;
  }
}

/* Studio Workstation Panels */
.studio-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: clamp(1.2rem, 2.5vw, 1.8rem);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  position: relative;
  backdrop-filter: blur(12px);
}

.studio-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.studio-title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.studio-subtitle {
  color: var(--text-muted);
  font-size: 0.92rem;
  margin-top: 0.25rem;
}

/* Mode Tabs */
.mode-tabs {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.45rem;
  background: var(--surface-card);
  padding: 0.35rem;
  border-radius: 14px;
  border: 1px solid var(--border);
}

@media (max-width: 640px) {
  .mode-tabs {
    grid-template-columns: repeat(2, 1fr);
  }
}

.mode-tab-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.3rem;
  padding: 0.65rem 0.5rem;
  border-radius: 10px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.mode-tab-btn:hover {
  color: var(--text);
  background: var(--surface-hover);
}

.mode-tab-btn.active {
  background: var(--surface-elevated);
  border-color: var(--border);
  color: var(--accent);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.mode-tab-btn svg {
  width: 1.25rem;
  height: 1.25rem;
}

/* Inspiration Chips */
.presets-section {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.section-label {
  font-size: 0.82rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-dim);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.chips-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.preset-chip {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 100px;
  padding: 0.38rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.preset-chip:hover {
  background: var(--surface-hover);
  border-color: var(--accent);
  color: var(--text);
  transform: translateY(-1px);
}

/* Form Fields */
.field {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
}

.field label {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
  display: flex;
  justify-content: space-between;
}

.field-hint {
  font-size: 0.8rem;
  color: var(--text-muted);
}

textarea, input[type="text"], input[type="url"], input[type="number"], select {
  width: 100%;
  font: inherit;
  color: var(--text);
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.75rem 0.95rem;
  outline: none;
  transition: all 0.2s ease;
}

textarea:focus, input[type="text"]:focus, input[type="url"]:focus, input[type="number"]:focus, select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

textarea {
  min-height: 96px;
  resize: vertical;
}

/* Mood Grid Cards */
.mood-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 0.6rem;
}

.mood-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.7rem 0.8rem;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  position: relative;
  overflow: hidden;
}

.mood-card:hover {
  border-color: var(--border-active);
  background: var(--surface-hover);
}

.mood-card.active {
  background: var(--surface-elevated);
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent), 0 0 16px var(--accent-glow);
}

.mood-color-strip {
  height: 4px;
  width: 100%;
  border-radius: 2px;
}

.mood-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mood-name {
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--text);
}

.mood-bpm {
  font-size: 0.72rem;
  font-family: "Space Grotesk", monospace;
  color: var(--text-dim);
  background: rgba(255, 255, 255, 0.05);
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
}

.mood-tag {
  font-size: 0.73rem;
  color: var(--text-muted);
  line-height: 1.3;
}

/* Visual Styles Grid */
.style-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.6rem;
}

.style-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.75rem;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.style-card:hover {
  background: var(--surface-hover);
  border-color: var(--border-active);
}

.style-card.active {
  background: var(--surface-elevated);
  border-color: var(--accent);
  box-shadow: 0 0 16px var(--accent-glow);
}

.style-name {
  font-size: 0.88rem;
  font-weight: 600;
  color: var(--text);
}

.style-desc {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.3;
}

/* Aspect Ratio Selector */
.ratio-options {
  display: flex;
  gap: 0.5rem;
}

.ratio-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 0.75rem;
  border-radius: 10px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.84rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.ratio-btn:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.ratio-btn.active {
  background: var(--surface-elevated);
  border-color: var(--accent);
  color: var(--accent);
}

/* Slider Controls */
.slider-container {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.slider-container input[type="range"] {
  flex: 1;
  accent-color: var(--accent);
  cursor: pointer;
}

.slider-value {
  font-family: "Space Grotesk", monospace;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--accent);
  min-width: 4.5rem;
  text-align: right;
  background: var(--surface-card);
  padding: 0.3rem 0.6rem;
  border-radius: 6px;
