  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
}

.deck-header {
  padding: 0.65rem 1rem;
  background: #110e1e;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--text-muted);
}

.deck-led {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 8px #10b981;
  margin-right: 0.4rem;
}

.deck-led.busy {
  background: #f59e0b;
  box-shadow: 0 0 8px #f59e0b;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  from { opacity: 0.4; }
  to { opacity: 1; }
}

.video-wrapper {
  width: 100%;
  background: #06050b;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 280px;
}

.video-wrapper video {
  width: 100%;
  max-height: 480px;
  display: block;
}

.video-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.8rem;
  color: var(--text-dim);
  text-align: center;
  padding: 3rem 1.5rem;
}

.video-placeholder svg {
  width: 3.5rem;
  height: 3.5rem;
  color: var(--text-dim);
  opacity: 0.6;
}

/* Action Bar below Video */
.deck-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.85rem;
  background: #110e1e;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.action-btn {
  flex: 1;
  min-width: 130px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding: 0.65rem 0.9rem;
  border-radius: 10px;
  background: var(--surface-card);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 0.85rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
}

.action-btn:hover:not(:disabled) {
  background: var(--surface-hover);
  border-color: var(--accent);
}

.action-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.action-btn.primary {
  background: var(--accent);
  color: var(--accent-text);
  border-color: var(--accent);
}

/* Live Equalizer Canvas */
.visualizer-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.eq-bars {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  height: 48px;
  padding: 4px 0;
}

.eq-bar {
  flex: 1;
  background: linear-gradient(to top, var(--accent), var(--coral));
  border-radius: 2px;
  min-height: 4px;
  transition: height 0.15s ease;
}

/* Ambient Audio Mixer Bar */
.ambient-mixer {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1rem 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.ambient-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ambient-title {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.92rem;
  font-weight: 600;
}

.ambient-toggle-btn {
  padding: 0.4rem 0.85rem;
  border-radius: 100px;
  border: 1px solid var(--border);
  background: var(--surface-elevated);
  color: var(--text);
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  transition: all 0.2s ease;
}

.ambient-toggle-btn.active {
  background: #10b981;
  border-color: #10b981;
  color: #fff;
  box-shadow: 0 0 12px rgba(16, 185, 129, 0.4);
}

.ambient-sliders {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.8rem;
}

@media (max-width: 640px) {
  .ambient-sliders {
    grid-template-columns: 1fr;
  }
}

.ambient-slider-item {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.78rem;
  color: var(--text-muted);
}

/* History Vault Drawer / Modal */
.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(8px);
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 1rem;
}

.modal-content {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 20px;
  width: 100%;
  max-width: 720px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
}

.modal-header {
  padding: 1.2rem 1.5rem;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.modal-body {
  padding: 1.5rem;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.history-item {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 0.9rem 1.1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  transition: all 0.2s ease;
}

.history-item:hover {
  background: var(--surface-hover);
  border-color: var(--accent);
}

.history-info {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  flex: 1;
}

.history-title {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--text);
}

.history-meta {
  font-size: 0.78rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 0.6rem;
}

.history-actions {
  display: flex;
  gap: 0.4rem;
}

/* Publishing Section */
.publish-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.publish-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.8rem;
}

@media (max-width: 640px) {
  .publish-grid {
    grid-template-columns: 1fr;
  }
}

/* Progress Tracker / Generation Modal */
.render-tracker {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.tracker-step {
  display: flex;
  align-items: center;
  gap: 0.8rem;
  font-size: 0.88rem;
  color: var(--text-muted);
}

.tracker-step.done {
  color: var(--success);
}

.tracker-step.active {
  color: var(--accent);
  font-weight: 600;
}

.step-indicator {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.72rem;
  border: 2px solid currentColor;
}

.step-indicator.spinning {
  border-top-color: transparent;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.toast {
  padding: 0.75rem 1rem;
  border-radius: 10px;
  font-size: 0.88rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.toast.ok {
  background: var(--success-bg);
  color: var(--success);
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.toast.error {
  background: var(--error-bg);
  color: var(--error);
  border: 1px solid rgba(239, 68, 68, 0.3);
}

/* Accessibility & Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

