  function handleVinylVol(v: number) {
    setVinylVol(v);
    ambientSound?.setVinylVolume(v / 100);
  }

  function handleRainVol(v: number) {
    setRainVol(v);
    ambientSound?.setRainVolume(v / 100);
  }

