    ambientSound?.setHissVolume(v / 100);
  }

  // Preset chip selection
  function applyPreset(p: (typeof PRESETS)[0]) {
    setPrompt(p.prompt);
    setMood(p.mood);
    setSeconds(p.seconds);
    setTitle(p.label + " Lofi Mix");
