    // Step simulation for UX feedback
    const t1 = setTimeout(() => setRenderStep(2), 2500);
    const t2 = setTimeout(() => setRenderStep(3), 6000);
    const t3 = setTimeout(() => setRenderStep(4), 11000);

    try {
      let data: Result;
      if (tool === "lofi-youtube") {
