      } else {
        if (!prompt.trim()) throw new Error("Enter a prompt describing your lofi mood.");
        data = await postJson("/api/generate", {
          prompt: prompt.trim(),
          seconds,
          style,
          mood,
          aspectRatio,
          watermark: watermark.trim(),
