import { writeFileSync } from "node:fs";

const SAMPLE_RATE = 44100;

const CHORDS = {
  Cmaj7: [261.63, 329.63, 392.0, 493.88],
  Am7: [220.0, 261.63, 329.63, 392.0],
  Fmaj7: [174.61, 220.0, 261.63, 329.63],
  G7: [196.0, 246.94, 293.66, 349.23],
  Dm7: [146.83, 174.61, 220.0, 261.63],
  Em7: [164.81, 196.0, 246.94, 293.66],
};

function synthLofiBeat(seconds = 10, bpm = 75) {
  const total = Math.floor(seconds * SAMPLE_RATE);
  const out = new Float32Array(total);
  const beatLen = 60 / bpm;
  const barLen = beatLen * 4;
  const stepLen = beatLen / 4; // 16th note

  // Progression: Dm7 -> G7 -> Cmaj7 -> Am7
  const progression = [CHORDS.Dm7, CHORDS.G7, CHORDS.Cmaj7, CHORDS.Am7];

  // 1. Synthesize Lofi Drums
  for (let t_sec = 0; t_sec < seconds; t_sec += barLen) {
    for (let step = 0; step < 16; step++) {
      const stepTime = t_sec + step * stepLen;
      if (stepTime >= seconds) break;
      const i0 = Math.floor(stepTime * SAMPLE_RATE);

      // Kick on 0, 7 (ghost), 8
      if (step === 0 || step === 8 || step === 7) {
        const vel = step === 7 ? 0.45 : 0.85;
        const kickLen = Math.floor(0.25 * SAMPLE_RATE);
        for (let i = 0; i < kickLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          const freq = 45 + 85 * Math.exp(-t * 28); // pitch sweep 130 -> 45 Hz
          const env = Math.exp(-t * 14);
          const sample = Math.sin(2 * Math.PI * freq * t) * env * vel;
          out[i0 + i] += Math.tanh(sample * 1.4) * 0.45;
        }
      }

      // Snare / Rimshot on 4, 12
      if (step === 4 || step === 12) {
        const snareLen = Math.floor(0.18 * SAMPLE_RATE);
        for (let i = 0; i < snareLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          const noise = (Math.random() * 2 - 1) * Math.exp(-t * 22);
          const tone = Math.sin(2 * Math.PI * 185 * t) * Math.exp(-t * 30);
          out[i0 + i] += (noise * 0.35 + tone * 0.25) * 0.4;
        }
      }

      // Hi-Hats on even steps + swing
      if (step % 2 === 0 || step === 10) {
        const isOpen = step === 10;
        const hatLen = Math.floor((isOpen ? 0.18 : 0.05) * SAMPLE_RATE);
        const vel = isOpen ? 0.35 : (step % 4 === 0 ? 0.25 : 0.16);
        for (let i = 0; i < hatLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          const noise = (Math.random() * 2 - 1) * Math.exp(-t * (isOpen ? 18 : 65));
          out[i0 + i] += noise * vel * 0.3;
        }
      }
    }
  }

  // 2. Synthesize Rhodes Electric Piano Chords
  for (let bar = 0; bar * barLen < seconds; bar++) {
    const barTime = bar * barLen;
    const chord = progression[bar % progression.length];

    // Play chord hit on beat 1 and a lighter syncopated hit on beat 2.5 (step 6)
    const hits = [
      { time: barTime, dur: barLen * 0.65, vel: 0.8 },
      { time: barTime + beatLen * 1.5, dur: barLen * 0.35, vel: 0.55 },
    ];

    for (const hit of hits) {
      if (hit.time >= seconds) break;
      const i0 = Math.floor(hit.time * SAMPLE_RATE);
      const hitSamples = Math.floor(hit.dur * SAMPLE_RATE);

      for (let i = 0; i < hitSamples && i0 + i < total; i++) {
        const t = i / SAMPLE_RATE;
        const env = Math.min(1, t / 0.015) * Math.exp(-t * 1.8);
        const wow = 1 + 0.0018 * Math.sin(2 * Math.PI * 0.3 * (hit.time + t));
        const tremolo = 0.88 + 0.12 * Math.sin(2 * Math.PI * 1.4 * (hit.time + t));

        let chordSample = 0;
        for (const freq of chord) {
          const p = 2 * Math.PI * freq * wow * t;
          chordSample += Math.sin(p) + 0.35 * Math.sin(2 * p) + 0.12 * Math.sin(3 * p) + 0.05 * Math.sin(4 * p);
        }

        // Sub bass
        const bassFreq = chord[0] * 0.5;
        const bass = Math.sin(2 * Math.PI * bassFreq * wow * t) * Math.exp(-t * 2.2);

        out[i0 + i] += (chordSample * 0.045 + bass * 0.12) * env * tremolo * hit.vel;
      }
    }
  }

  // 3. Lowpass filter & Vinyl crackle
  let lp = 0;
  for (let i = 0; i < total; i++) {
    let x = out[i];
    if (Math.random() < 0.00035) x += (Math.random() * 2 - 1) * 0.15; // vinyl tick
    lp += 0.35 * (x - lp); // warm analog filter
    out[i] = lp;
  }

  // Master fade in/out
  const fade = Math.floor(SAMPLE_RATE * 0.5);
  for (let i = 0; i < total; i++) {
    let g = 1;
    if (i < fade) g = i / fade;
    if (total - i < fade) g = (total - i) / fade;
    out[i] *= g;
  }

  // Write WAV
  const dataBytes = total * 2;
  const buf = Buffer.alloc(44 + dataBytes);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + dataBytes, 4);
  buf.write("WAVE", 8);
  buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(SAMPLE_RATE, 24);
  buf.writeUInt32LE(SAMPLE_RATE * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(dataBytes, 40);
  for (let i = 0; i < total; i++) {
    const v = Math.max(-1, Math.min(1, out[i]));
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync("scratch/test_lofi.wav", buf);
  console.log("Successfully rendered scratch/test_lofi.wav!");
}

