import { writeFileSync } from "node:fs";

const SAMPLE_RATE = 44100;

const CHORDS = {
  Cmaj7: [261.63, 329.63, 392.0, 493.88],
  Am7: [220.0, 261.63, 329.63, 392.0],
  Fmaj7: [174.61, 220.0, 261.63, 329.63],
  G7: [196.0, 246.94, 293.66, 349.23],
  Dm7: [146.83, 174.61, 220.0, 261.63],
  Em7: [164.81, 196.0, 246.94, 293.66],
  Bm7: [246.94, 293.66, 369.99, 440.0],
  E7: [164.81, 207.65, 246.94, 293.66],
  Amaj7: [220.0, 277.18, 329.63, 415.3],
  Dmaj7: [146.83, 185.0, 220.0, 277.18],
  Bbmaj7: [233.08, 293.66, 349.23, 440.0],
  Gm7: [196.0, 233.08, 293.66, 349.23],
};

export const MOODS = {
  night: {
    label: "Night Rain",
    bpm: 74,
    progression: ["Dm7", "G7", "Cmaj7", "Am7"],
    colors: ["0x0b1d33", "0x2a4a6b"],
    tag: "Late night study & gentle rain",
    defaultBg: "bg_rain.gif",
  },
  sunset: {
    label: "Golden Hour",
    bpm: 78,
    progression: ["Fmaj7", "Em7", "Dm7", "Cmaj7"],
    colors: ["0x3a1c2e", "0xd9793f"],
    tag: "Warm dusk breeze & rooftop vibes",
    defaultBg: "bg_study.gif",
  },
  morning: {
    label: "Slow Morning",
    bpm: 72,
    progression: ["Cmaj7", "Dm7", "Em7", "Fmaj7"],
    colors: ["0x253b30", "0xdfbe99"],
    tag: "Fresh brewed coffee & morning calm",
    defaultBg: "bg_chill.gif",
  },
  lofi_cafe: {
    label: "Cozy Cafe",
    bpm: 75,
    progression: ["Cmaj7", "Em7", "Am7", "Dm7"],
    colors: ["0x261910", "0xa36842"],
    tag: "Rainy bookstore & warm espresso",
    defaultBg: "bg_cafe.gif",
  },
  cyberpunk: {
    label: "Neon Midnight",
    bpm: 82,
    progression: ["Am7", "Fmaj7", "Dm7", "Em7"],
    colors: ["0x110e2b", "0x632d84"],
    tag: "Tokyo synth reflections & neon mist",
    defaultBg: "bg_drive.gif",
  },
  dreamy: {
    label: "Starlight Drift",
    bpm: 70,
    progression: ["Fmaj7", "G7", "Em7", "Am7"],
    colors: ["0x12142e", "0x534ba0"],
    tag: "Cosmic floating & deep slumber",
    defaultBg: "bg_night.gif",
  },
  autumn: {
    label: "Autumn Leaves",
    bpm: 76,
    progression: ["Dm7", "Am7", "Bbmaj7", "Cmaj7"],
    colors: ["0x2a1612", "0x9e4324"],
    tag: "Fallen leaves & vintage cassette nostalgia",
    defaultBg: "bg_study.gif",
  },
};

export function pickMood(prompt) {
  if (!prompt || typeof prompt !== "string") return "night";
  const p = prompt.toLowerCase();
  if (/neon|cyber|synth|future|tokyo|blade|matrix|drive/.test(p)) return "cyberpunk";
  if (/cafe|coffee|book|library|tea|bakery|espresso|acoustic/.test(p)) return "lofi_cafe";
  if (/dream|star|space|cosmic|cloud|drift|sleep|celestial/.test(p)) return "dreamy";
  if (/autumn|fall|leaves|october|ember|harvest|wood/.test(p)) return "autumn";
  if (/sunset|golden|warm|dusk|evening|twilight/.test(p)) return "sunset";
  if (/morning|sun|cozy|breakfast|dawn|light|fresh/.test(p)) return "morning";
  return "night";
}

function seededRandom(seedStr) {
  let h = 2166136261;
  for (const ch of seedStr) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  if (h === 0) h = 1;
  return () => {
    h ^= h << 13;
    h ^= h >>> 17;
    h ^= h << 5;
    return (h >>> 0) / 4294967296;
  };
}

export function synthesizeLofi(moodKey, seconds, seed) {
  const m = MOODS[moodKey] || MOODS.night;
  const rand = seededRandom(seed || "lofi-master");
  const total = Math.floor(seconds * SAMPLE_RATE);
  const out = new Float32Array(total);

  const bpm = m.bpm || 75;
  const beatLen = 60 / bpm;
  const barLen = beatLen * 4;
  const stepLen = beatLen / 4; // 16th note

  // Progression
  const progression = m.progression.map((name) => CHORDS[name] || CHORDS.Cmaj7);

  // 1. Synthesize Lofi Drum Kit (Kick, Snare/Rimshot, Hi-hats)
  for (let t_sec = 0; t_sec < seconds; t_sec += barLen) {
    for (let step = 0; step < 16; step++) {
      const stepTime = t_sec + step * stepLen;
      if (stepTime >= seconds) break;
      const i0 = Math.floor(stepTime * SAMPLE_RATE);

      // Kick drum on 0, 7 (ghost kick), 8
      if (step === 0 || step === 8 || step === 7) {
        const vel = step === 7 ? 0.45 : 0.85;
        const kickLen = Math.floor(0.28 * SAMPLE_RATE);
        for (let i = 0; i < kickLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          // Pitch sweep 140 -> 46 Hz
          const freq = 46 + 94 * Math.exp(-t * 26);
          const env = Math.exp(-t * 13);
          const sample = Math.sin(2 * Math.PI * freq * t) * env * vel;
          out[i0 + i] += Math.tanh(sample * 1.5) * 0.48;
        }
      }

      // Snare / Rimshot on 4, 12
      if (step === 4 || step === 12) {
        const snareLen = Math.floor(0.2 * SAMPLE_RATE);
        for (let i = 0; i < snareLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          const noise = (rand() * 2 - 1) * Math.exp(-t * 24);
          const tone = Math.sin(2 * Math.PI * 185 * t) * Math.exp(-t * 32);
          out[i0 + i] += (noise * 0.4 + tone * 0.3) * 0.42;
        }
      }

      // Hi-Hats on even steps + swing on step 10
      if (step % 2 === 0 || step === 10) {
        const isOpen = step === 10;
        const hatLen = Math.floor((isOpen ? 0.18 : 0.05) * SAMPLE_RATE);
        const vel = isOpen ? 0.4 : (step % 4 === 0 ? 0.28 : 0.18);
        for (let i = 0; i < hatLen && i0 + i < total; i++) {
          const t = i / SAMPLE_RATE;
          const noise = (rand() * 2 - 1) * Math.exp(-t * (isOpen ? 18 : 65));
          out[i0 + i] += noise * vel * 0.32;
        }
      }
    }
  }

  // 2. Synthesize Rhodes Electric Piano Chords & Bassline
  for (let bar = 0; bar * barLen < seconds; bar++) {
    const barTime = bar * barLen;
    const chord = progression[bar % progression.length];

    // Downbeat chord strike + syncopated offbeat tap
    const hits = [
      { time: barTime, dur: barLen * 0.68, vel: 0.85 },
      { time: barTime + beatLen * 1.5, dur: barLen * 0.32, vel: 0.58 },
    ];

    for (const hit of hits) {
      if (hit.time >= seconds) break;
      const i0 = Math.floor(hit.time * SAMPLE_RATE);
      const hitSamples = Math.floor(hit.dur * SAMPLE_RATE);

      for (let i = 0; i < hitSamples && i0 + i < total; i++) {
        const t = i / SAMPLE_RATE;
        // Key strike attack & smooth decay
        const env = Math.min(1, t / 0.012) * Math.exp(-t * 1.6);
        // Analog tape wow & flutter
        const wow = 1 + 0.0016 * Math.sin(2 * Math.PI * 0.3 * (hit.time + t));
        // Vintage stereo tremolo
        const tremolo = 0.86 + 0.14 * Math.sin(2 * Math.PI * 1.4 * (hit.time + t));

        let chordSample = 0;
        for (const freq of chord) {
          const p = 2 * Math.PI * freq * wow * t;
          chordSample += Math.sin(p) + 0.38 * Math.sin(2 * p) + 0.14 * Math.sin(3 * p) + 0.06 * Math.sin(4 * p);
        }

        // Sub bass on root frequency
        const bassFreq = chord[0] * 0.5;
        const bass = Math.sin(2 * Math.PI * bassFreq * wow * t) * Math.exp(-t * 2.0);

        out[i0 + i] += (chordSample * 0.055 + bass * 0.15) * env * tremolo * hit.vel;
      }
    }
  }

  // 3. Vintage Lowpass Filtering, Tape Hiss & Vinyl Crackle
  let lp = 0;
  for (let i = 0; i < total; i++) {
    let x = out[i];
    // Gentle tape hiss
    x += (rand() * 2 - 1) * 0.004;
    // Vinyl crackle / pop
    if (rand() < 0.00035) x += (rand() * 2 - 1) * 0.18;
    // Warm lowpass filter
    lp += 0.36 * (x - lp);
    out[i] = lp;
  }

  // 4. Master Normalization & Fade In/Out
  let peak = 0;
  for (let i = 0; i < total; i++) peak = Math.max(peak, Math.abs(out[i]));
  const gain = peak > 0 ? 0.88 / peak : 1;
  const fade = Math.min(Math.floor(SAMPLE_RATE * 0.6), Math.floor(total / 4));
  for (let i = 0; i < total; i++) {
    let g = gain;
    if (i < fade) g *= i / fade;
    if (total - i < fade) g *= (total - i) / fade;
    out[i] *= g;
  }

  return out;
}

function writeWav(filePath, samples) {
  const dataBytes = samples.length * 2;
  const buf = Buffer.alloc(44 + dataBytes);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + dataBytes, 4);
  buf.write("WAVE", 8);
  buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(SAMPLE_RATE, 24);
  buf.writeUInt32LE(SAMPLE_RATE * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(dataBytes, 40);
  for (let i = 0; i < samples.length; i++) {
    const v = Math.max(-1, Math.min(1, samples[i]));
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(filePath, buf);
}

export function renderWav(filePath, { mood, seconds, seed }) {
  writeWav(filePath, synthesizeLofi(mood, seconds, seed));
}

import http from "node:http";
import { createReadStream } from "node:fs";
import { copyFile, mkdir, readFile, writeFile, stat, readdir } from "node:fs/promises";
import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { MOODS, pickMood, renderWav } from "./generate.mjs";
import { publishToYouTube, publishToInstagram } from "./publish.mjs";

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC = path.join(ROOT, "public");
const OUT = path.join(ROOT, "outputs");
const BGS = path.join(PUBLIC, "backgrounds");
const PORT = Number(process.env.PORT) || 3000;
const FFMPEG = process.env.FFMPEG || "ffmpeg";
const PYTHON = process.env.PYTHON || "python";
const FONT_SRC = process.env.FONT_FILE || "C:/Windows/Fonts/arial.ttf";
const PUBLIC_BASE_URL = (process.env.PUBLIC_BASE_URL || "").replace(/\/$/, "");
const MIN_SECONDS = 10;
const MAX_SECONDS = 240;
const MAX_GIF_BYTES = 20 * 1024 * 1024;
const JOB_ID = /^[a-f0-9]{8}$/;
const STYLE_NAMES = { lofi: "Lofi", anime: "Anime", pixar: "Pixar" };
const STYLE_FILTERS = {
  anime: "[bg0]hqdn3d=3:2:5:4,eq=saturation=1.45:contrast=1.12,unsharp=5:5:1.1:5:5:0[bg]",
  pixar: "[bg0]split[a][b];[b]gblur=sigma=14[g];[a][g]blend=all_mode=screen:all_opacity=0.35,eq=saturation=1.2:brightness=0.03:gamma=1.08,colorbalance=rs=0.05:gs=0.02:bs=-0.03[bg]",
};

const SCENES = [
  { id: "bg_study.gif", label: "Anime Study Girl", tag: "Classic Lofi Girl desk & warm lamp", url: "/backgrounds/bg_study.gif" },
  { id: "bg_rain.gif", label: "Cozy Rainy Window", tag: "Raindrops falling & cat watching glass", url: "/backgrounds/bg_rain.gif" },
  { id: "bg_cafe.gif", label: "Warm Rainy Cafe", tag: "Coffee cup with rising steam & rain", url: "/backgrounds/bg_cafe.gif" },
  { id: "bg_drive.gif", label: "Tokyo Neon Drive", tag: "Cyberpunk rain highway & neon reflections", url: "/backgrounds/bg_drive.gif" },
  { id: "bg_night.gif", label: "Starlit Bedroom", tag: "Celestial starry night & cozy bed", url: "/backgrounds/bg_night.gif" },
  { id: "bg_chill.gif", label: "Cozy Morning Bedroom", tag: "Warm sunlight & morning laptop chill", url: "/backgrounds/bg_chill.gif" },
];

function parseStyle(v) {
  const s = typeof v === "string" && v ? v : "lofi";
  if (!Object.hasOwn(STYLE_NAMES, s)) throw new Error("Unknown style");
  return s;
}

function parseAspectRatio(v) {
  return ["16:9", "9:16", "1:1"].includes(v) ? v : "16:9";
}

function getLayoutConfig(aspectRatio = "16:9") {
  if (aspectRatio === "9:16") {
    return {
      width: 720,
      height: 1280,
      waveHeight: 200,
      waveY: 980,
      titleY: "380",
      titleSize: 42,
      subY: "450",
      subSize: 24,
      wmY: "h-text_h-30",
      wmX: "w-text_w-30",
      wmSize: 22,
    };
  }
  if (aspectRatio === "1:1") {
    return {
      width: 720,
      height: 720,
      waveHeight: 140,
      waveY: 530,
      titleY: "190",
      titleSize: 40,
      subY: "250",
      subSize: 22,
      wmY: "h-text_h-20",
      wmX: "w-text_w-20",
      wmSize: 20,
    };
  }
  // 16:9 default
  return {
    width: 1280,
    height: 720,
    waveHeight: 160,
    waveY: 520,
    titleY: "170",
    titleSize: 52,
    subY: "245",
    subSize: 26,
    wmY: "h-text_h-20",
    wmX: "w-text_w-20",
    wmSize: 24,
  };
}

function runProcess(cmd, args, cwd) {
  return new Promise((resolve, reject) => {
    const proc = spawn(cmd, args, { cwd, windowsHide: true });
    let stderr = "";
    proc.stderr.on("data", (d) => (stderr += d));
    proc.on("error", reject);
    proc.on("close", (code) => {
      if (code === 0) resolve(stderr);
      else reject(new Error(`${path.basename(cmd)} exited ${code}: ${stderr.slice(-800)}`));
    });
  });
}

function parseYoutubeUrl(raw) {
  let u;
  try {
    u = new URL(raw);
  } catch {
    throw new Error("Invalid YouTube URL");
  }
  const host = u.hostname.replace(/^www\./, "");
  if (!["youtube.com", "m.youtube.com", "youtu.be"].includes(host)) {
    throw new Error("URL must be a youtube.com or youtu.be link");
  }
  return u.toString();
}

async function downloadYoutubeAudio(url, seconds, jobDir) {
  await runProcess(
    PYTHON,
    [
      "-m", "yt_dlp",
      "-x", "--audio-format", "wav",
      "--no-playlist",
      "--download-sections", `*0-${seconds}`,
      "--force-keyframes-at-cuts",
      "-o", "audio.%(ext)s",
      url,
    ],
    jobDir,
  );
}

async function downloadGif(url, jobDir) {
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error("Invalid GIF URL");
  }
  if (!["http:", "https:"].includes(parsed.protocol)) throw new Error("GIF URL must be http(s)");
  const res = await fetch(parsed);
  if (!res.ok) throw new Error(`GIF download failed: ${res.status}`);
  const buf = Buffer.from(await res.arrayBuffer());
  if (buf.length > MAX_GIF_BYTES) throw new Error("GIF is larger than 20 MB");
  await writeFile(path.join(jobDir, "bg.gif"), buf);
}

async function renderMp4(jobDir, { seconds, bg, title, sub, watermark, timed = [], style = "lofi", aspectRatio = "16:9" }) {
  await copyFile(FONT_SRC, path.join(jobDir, "font.ttf"));
  const layout = getLayoutConfig(aspectRatio);

  let inputs;
  if (bg.kind === "gif") {
    // If local GIF provided, copy or link to jobDir
    if (bg.localFile) {
      await copyFile(bg.localFile, path.join(jobDir, "bg.gif")).catch(() => {});
    }
    inputs = ["-stream_loop", "-1", "-i", "bg.gif"];
  } else {
    inputs = ["-f", "lavfi", "-i", `gradients=s=${layout.width}x${layout.height}:c0=${bg.colors[0]}:c1=${bg.colors[1]}:speed=0.01:rate=30:duration=${seconds}`];
  }

  const bgLabel = style === "lofi" ? "bg" : "bg0";
  const chain = [
    `[0:v]scale=${layout.width}:${layout.height}:force_original_aspect_ratio=increase,crop=${layout.width}:${layout.height},setsar=1,fps=30[${bgLabel}]`,
    `[1:a]showwaves=s=${layout.width}x${layout.waveHeight}:mode=cline:colors=0xf59e0b@0.85:rate=30[w]`,
    `[bg][w]overlay=0:${layout.waveY}:format=auto[v0]`,
  ];
  if (style !== "lofi") chain.splice(1, 0, STYLE_FILTERS[style]);
  let last = "v0";
  const texts = [];
  if (title) texts.push({ file: "title.txt", text: title.slice(0, 60), size: layout.titleSize, color: "white", y: layout.titleY, x: "(w-text_w)/2" });
  if (sub) texts.push({ file: "sub.txt", text: sub, size: layout.subSize, color: "white@0.8", y: layout.subY, x: "(w-text_w)/2" });
  if (watermark) texts.push({ file: "wm.txt", text: watermark.slice(0, 60), size: layout.wmSize, color: "white@0.6", y: layout.wmY, x: layout.wmX });
  texts.push(...timed);

  for (const [i, t] of texts.entries()) {
    await writeFile(path.join(jobDir, t.file), t.text);
    const enable = t.enable ? `:enable='${t.enable}'` : "";
    chain.push(`[${last}]drawtext=fontfile=font.ttf:textfile=${t.file}:fontcolor=${t.color}:fontsize=${t.size}:x=${t.x}:y=${t.y}${enable}:shadowcolor=black@0.6:shadowx=2:shadowy=2[t${i}]`);
    last = `t${i}`;
  }
  // Ensure universal browser compatibility with yuv420p
  chain.push(`[${last}]format=yuv420p[v]`);

  const args = [
    "-y", "-hide_banner", "-loglevel", "error",
    ...inputs,
    "-i", "audio.wav",
    "-filter_complex", chain.join(";"),
    "-map", "[v]", "-map", "1:a",
    "-t", String(seconds),
    "-c:v", "libx264", "-preset", "veryfast", "-crf", "22",
    "-pix_fmt", "yuv420p",
    "-c:a", "aac", "-b:a", "192k",
    "-movflags", "+faststart",
    "out.mp4",
  ];
  await runProcess(FFMPEG, args, jobDir);
}

async function newJob(meta = {}) {
  const id = randomUUID().slice(0, 8);
  const jobDir = path.join(OUT, id);
  await mkdir(jobDir, { recursive: true });
  const fullMeta = { id, createdAt: Date.now(), ...meta };
  await writeFile(path.join(jobDir, "meta.json"), JSON.stringify(fullMeta, null, 2)).catch(() => {});
  return { id, jobDir };
}

async function generateFromMood({ prompt, seconds, style = "lofi", moodOverride, sceneOverride, gifUrl, aspectRatio = "16:9", watermark = "" }) {
  const mood = (moodOverride && MOODS[moodOverride]) ? moodOverride : pickMood(prompt);
  const m = MOODS[mood];

  // Pick animated background: custom GIF URL > selected scene > default mood animated GIF
  let bg;
  const bgFilename = sceneOverride || m.defaultBg || "bg_study.gif";
  const localBgPath = path.join(BGS, bgFilename);

  const { id, jobDir } = await newJob({
    prompt,
    mood,
    moodLabel: m.label,
    seconds,
    style,
    aspectRatio,
    title: prompt.slice(0, 60),
    sub: m.label,
    bgScene: bgFilename,
  });

  if (gifUrl) {
    await downloadGif(gifUrl, jobDir);
    bg = { kind: "gif" };
  } else {
    // Check if local animated GIF exists
    try {
      await stat(localBgPath);
      bg = { kind: "gif", localFile: localBgPath };
    } catch {
      bg = { kind: "gradient", colors: m.colors };
    }
  }

  // Synthesize authentic lofi hip hop audio with drums and rhodes piano
  renderWav(path.join(jobDir, "audio.wav"), { mood, seconds, seed: prompt + id });

  await renderMp4(jobDir, {
    seconds,
    bg,
    title: prompt.slice(0, 60),
    sub: m.label,
    watermark,
    style,
    aspectRatio,
  });

  const label = style === "lofi" ? m.label : `${STYLE_NAMES[style]} look, ${m.label}`;
  return { id, label, mood, bgScene: bgFilename };
}

async function generateFromYoutube({ youtubeUrl, seconds, gifUrl, sceneOverride, watermark, aspectRatio = "16:9" }) {
  const url = parseYoutubeUrl(youtubeUrl);
  const bgFilename = sceneOverride || "bg_study.gif";
  const localBgPath = path.join(BGS, bgFilename);

  const { id, jobDir } = await newJob({
    type: "youtube",
    youtubeUrl,
    seconds,
    gifUrl,
    aspectRatio,
    title: "YouTube Audio Remix",
    sub: "Lofi Remix",
    bgScene: bgFilename,
  });

  await downloadYoutubeAudio(url, seconds, jobDir);

  let bg;
  if (gifUrl) {
    await downloadGif(gifUrl, jobDir);
    bg = { kind: "gif" };
  } else {
    try {
      await stat(localBgPath);
      bg = { kind: "gif", localFile: localBgPath };
    } catch {
      bg = { kind: "gradient", colors: MOODS.night.colors };
    }
  }

  await renderMp4(jobDir, { seconds, bg, title: null, sub: null, watermark: watermark || "", aspectRatio });
  return { id, label: "YouTube audio" };
}

async function generateSlides({ scenes, seconds, watermark, sceneOverride, aspectRatio = "16:9" }) {
  const lines = scenes.split("\n").map((s) => s.trim()).filter(Boolean).slice(0, 12);
  if (!lines.length) throw new Error("Add at least one scene line");
  const mood = pickMood(lines.join(" "));
  const m = MOODS[mood];

  const bgFilename = sceneOverride || m.defaultBg || "bg_rain.gif";
  const localBgPath = path.join(BGS, bgFilename);

  const { id, jobDir } = await newJob({
    type: "slides",
    mood,
    moodLabel: m.label,
    scenes: lines,
    seconds,
    aspectRatio,
    title: lines[0] || "Story Slides",
    sub: `${lines.length} scene${lines.length > 1 ? "s" : ""}`,
    bgScene: bgFilename,
  });

  renderWav(path.join(jobDir, "audio.wav"), { mood, seconds, seed: lines.join("|") + id });

  let bg;
  try {
    await stat(localBgPath);
    bg = { kind: "gif", localFile: localBgPath };
  } catch {
    bg = { kind: "gradient", colors: m.colors };
  }

  const step = seconds / lines.length;
  const timed = lines.map((line, i) => ({
    file: `scene${i}.txt`,
    text: line.slice(0, 60),
    size: 38,
    color: "white",
    x: "(w-text_w)/2",
    y: "(h-text_h)/2",
    enable: `between(t,${(i * step).toFixed(2)},${((i + 1) * step).toFixed(2)})`,
  }));

  await renderMp4(jobDir, {
    seconds,
    bg,
    title: null,
    sub: null,
    watermark: watermark || "",
    timed,
    aspectRatio,
  });

  return { id, label: `${lines.length} scene${lines.length > 1 ? "s" : ""}` };
}

async function trimSilence(jobId) {
  const srcDir = path.join(OUT, jobId);
  const src = path.join(srcDir, "out.mp4");
  const log = await runProcess(
    FFMPEG,
    ["-hide_banner", "-nostats", "-i", src, "-vn", "-af", "silencedetect=noise=-35dB:d=0.6", "-f", "null", "-"],
    srcDir,
  );
  const dm = /Duration: (\d+):(\d+):([\d.]+)/.exec(log);
  if (!dm) throw new Error("Could not read video duration");
  const total = Number(dm[1]) * 3600 + Number(dm[2]) * 60 + Number(dm[3]);
  const starts = [...log.matchAll(/silence_start: ([\d.]+)/g)].map((m) => Number(m[1]));
  const ends = [...log.matchAll(/silence_end: ([\d.]+)/g)].map((m) => Number(m[1]));
  const PAD = 0.15;
  const keep = [];
  let cursor = 0;
  starts.forEach((s, i) => {
    const e = ends[i] ?? total;
    if (s > cursor) keep.push([cursor, Math.min(total, s + PAD)]);
    cursor = Math.max(cursor, e - PAD);
  });
  if (cursor < total) keep.push([cursor, total]);
  const segs = keep.filter(([a, b]) => b - a > 0.1);
  const keptTotal = segs.reduce((n, [a, b]) => n + b - a, 0);
  if (!segs.length || total - keptTotal < 0.5) throw new Error("Nothing to trim: no long pauses found");
  if (segs.length > 300) throw new Error("Too many pauses to trim");

  const expr = segs.map(([a, b]) => `between(t,${a.toFixed(3)},${b.toFixed(3)})`).join("+");
  const { id, jobDir } = await newJob({ type: "trimmed", sourceJobId: jobId, removedSeconds: total - keptTotal });
  await runProcess(
    FFMPEG,
    [
      "-y", "-hide_banner", "-loglevel", "error",
      "-i", src,
      "-filter_complex", `[0:v]select='${expr}',setpts=N/FRAME_RATE/TB[v];[0:a]aselect='${expr}',asetpts=N/SR/TB[a]`,
      "-map", "[v]", "-map", "[a]",
      "-c:v", "libx264", "-preset", "veryfast", "-crf", "22",
      "-pix_fmt", "yuv420p",
      "-c:a", "aac", "-b:a", "192k",
      "-movflags", "+faststart",
      "out.mp4",
    ],
    jobDir,
  );
  return { id, removedSeconds: total - keptTotal };
}

function sendJson(res, status, body) {
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  });
  res.end(JSON.stringify(body));
}

async function readBody(req) {
  let data = "";
  for await (const chunk of req) {
    data += chunk;
    if (data.length > 10_000) throw new Error("Body too large");
  }
  return data ? JSON.parse(data) : {};
}

function clampSeconds(v) {
  return Math.min(MAX_SECONDS, Math.max(MIN_SECONDS, Number(v) || 60));
}

async function withBody(req, res, handler) {
  let body;
  try {
    body = await readBody(req);
  } catch {
    return sendJson(res, 400, { error: "Invalid JSON" });
  }
  try {
    sendJson(res, 200, await handler(body));
  } catch (err) {
    console.error(err);
    sendJson(res, 500, { error: err.message });
  }
}

function handleGenerate(req, res) {
  return withBody(req, res, async (body) => {
    const prompt = typeof body.prompt === "string" ? body.prompt.trim() : "";
    if (!prompt || prompt.length > 200) throw new Error("Prompt must be 1-200 characters");
    const seconds = clampSeconds(body.seconds);
    const style = parseStyle(body.style);
    const aspectRatio = parseAspectRatio(body.aspectRatio);
    const moodOverride = typeof body.mood === "string" ? body.mood : null;
    const sceneOverride = typeof body.scene === "string" ? body.scene : null;
    const gifUrl = typeof body.gifUrl === "string" && body.gifUrl.trim() ? body.gifUrl.trim() : null;
    const watermark = typeof body.watermark === "string" ? body.watermark.trim().slice(0, 60) : "";

    const r = await generateFromMood({ prompt, seconds, style, moodOverride, sceneOverride, gifUrl, aspectRatio, watermark });
    return {
      id: r.id,
      moodLabel: r.label,
      mood: r.mood,
      bgScene: r.bgScene,
      url: `/outputs/${r.id}/out.mp4`,
      audioUrl: `/outputs/${r.id}/audio.wav`,
      aspectRatio,
    };
  });
}

function handleFromYoutube(req, res) {
  return withBody(req, res, async (body) => {
    if (typeof body.youtubeUrl !== "string" || !body.youtubeUrl.trim()) throw new Error("YouTube URL is required");
    const seconds = clampSeconds(body.seconds);
    const gifUrl = typeof body.gifUrl === "string" && body.gifUrl.trim() ? body.gifUrl.trim() : null;
    const sceneOverride = typeof body.scene === "string" ? body.scene : null;
    const watermark = typeof body.watermark === "string" ? body.watermark.trim().slice(0, 60) : "";
    const aspectRatio = parseAspectRatio(body.aspectRatio);

    const r = await generateFromYoutube({ youtubeUrl: body.youtubeUrl.trim(), seconds, gifUrl, sceneOverride, watermark, aspectRatio });
    return {
      id: r.id,
      moodLabel: r.label,
      url: `/outputs/${r.id}/out.mp4`,
      audioUrl: `/outputs/${r.id}/audio.wav`,
      aspectRatio,
    };
  });
}

function handlePublish(req, res) {
  return withBody(req, res, async (body) => {
    if (!JOB_ID.test(body.jobId || "")) throw new Error("Invalid job id");
    const filePath = path.join(OUT, body.jobId, "out.mp4");
    const title = typeof body.title === "string" && body.title.trim() ? body.title.trim() : "Lofi video";
    const description = typeof body.description === "string" ? body.description : "";

    if (body.target === "youtube") {
      return { target: "youtube", ...(await publishToYouTube({ filePath, title, description, privacy: body.privacy })) };
    }
    if (body.target === "instagram") {
      if (!PUBLIC_BASE_URL) throw new Error("Instagram needs a public video URL: set PUBLIC_BASE_URL (for example an ngrok or tunnel address)");
      const videoUrl = `${PUBLIC_BASE_URL}/outputs/${body.jobId}/out.mp4`;
      return { target: "instagram", ...(await publishToInstagram({ videoUrl, caption: `${title}\n${description}`.trim() })) };
    }
    throw new Error("target must be youtube or instagram");
  });
}

function handleSlides(req, res) {
  return withBody(req, res, async (body) => {
    const scenes = typeof body.scenes === "string" ? body.scenes : "";
    const seconds = clampSeconds(body.seconds);
    const watermark = typeof body.watermark === "string" ? body.watermark.trim().slice(0, 60) : "";
    const sceneOverride = typeof body.scene === "string" ? body.scene : null;
    const aspectRatio = parseAspectRatio(body.aspectRatio);

    const r = await generateSlides({ scenes, seconds, watermark, sceneOverride, aspectRatio });
    return {
      id: r.id,
      moodLabel: r.label,
      url: `/outputs/${r.id}/out.mp4`,
      audioUrl: `/outputs/${r.id}/audio.wav`,
      aspectRatio,
    };
  });
}

function handleTrimSilence(req, res) {
  return withBody(req, res, async (body) => {
    if (!JOB_ID.test(body.jobId || "")) throw new Error("Invalid job id");
    const r = await trimSilence(body.jobId);
    return {
      id: r.id,
      removedSeconds: r.removedSeconds,
      url: `/outputs/${r.id}/out.mp4`,
      audioUrl: `/outputs/${r.id}/audio.wav`,
    };
  });
}

async function handleHistory(req, res) {
  try {
    const entries = await readdir(OUT, { withFileTypes: true });
    const items = [];
    for (const dirent of entries) {
      if (!dirent.isDirectory()) continue;
      const id = dirent.name;
      if (!JOB_ID.test(id)) continue;
      const jobDir = path.join(OUT, id);
      try {
        const mp4Stat = await stat(path.join(jobDir, "out.mp4"));
        let meta = {};
        try {
          meta = JSON.parse(await readFile(path.join(jobDir, "meta.json"), "utf-8"));
        } catch {
          let title = "";
          let sub = "";
          try { title = (await readFile(path.join(jobDir, "title.txt"), "utf-8")).trim(); } catch {}
          try { sub = (await readFile(path.join(jobDir, "sub.txt"), "utf-8")).trim(); } catch {}
          meta = { id, title: title || `Lofi Mix #${id}`, sub: sub || "Lofi Studio", createdAt: mp4Stat.mtimeMs };
        }
        items.push({
          id,
          url: `/outputs/${id}/out.mp4`,
          audioUrl: `/outputs/${id}/audio.wav`,
          title: meta.title || `Lofi Mix #${id}`,
          sub: meta.sub || meta.moodLabel || "Lofi Studio",
          mood: meta.mood,
          style: meta.style || "lofi",
          seconds: meta.seconds || 60,
          aspectRatio: meta.aspectRatio || "16:9",
          createdAt: meta.createdAt || mp4Stat.mtimeMs,
          size: mp4Stat.size,
          bgScene: meta.bgScene,
        });
      } catch {
        // out.mp4 not present or failed
      }
    }
    items.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    sendJson(res, 200, { items });
  } catch (err) {
    sendJson(res, 500, { error: err.message });
  }
}

function handleMoods(req, res) {
  const moods = Object.entries(MOODS).map(([key, val]) => ({
    id: key,
    label: val.label,
    bpm: val.bpm,
    tag: val.tag || "",
    colors: val.colors,
    defaultBg: val.defaultBg,
  }));
  sendJson(res, 200, { moods, scenes: SCENES });
}

async function serveFile(res, filePath, contentType) {
  try {
    const s = await stat(filePath);
    if (!s.isFile()) throw new Error("not a file");
  } catch {
    res.writeHead(404);
    return res.end("Not found");
  }
  res.writeHead(200, {
    "Content-Type": contentType,
    "Access-Control-Allow-Origin": "*",
    "Cache-Control": "public, max-age=3600",
  });
  createReadStream(filePath).pipe(res);
}

const TYPES = {
  ".html": "text/html",
  ".mp4": "video/mp4",
  ".js": "text/javascript",
  ".css": "text/css",
  ".wav": "audio/wav",
  ".json": "application/json",
  ".gif": "image/gif",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".webp": "image/webp",
};

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === "OPTIONS") {
    res.writeHead(204, {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
    });
    return res.end();
  }

  if (req.method === "GET" && url.pathname === "/api/history") return handleHistory(req, res);
  if (req.method === "GET" && url.pathname === "/api/moods") return handleMoods(req, res);
  if (req.method === "GET" && url.pathname === "/api/scenes") return sendJson(res, 200, { scenes: SCENES });

  if (req.method === "POST" && url.pathname === "/api/generate") return handleGenerate(req, res);
  if (req.method === "POST" && url.pathname === "/api/from-youtube") return handleFromYoutube(req, res);
  if (req.method === "POST" && url.pathname === "/api/publish") return handlePublish(req, res);
  if (req.method === "POST" && url.pathname === "/api/slides") return handleSlides(req, res);
  if (req.method === "POST" && url.pathname === "/api/trim-silence") return handleTrimSilence(req, res);

  if (req.method === "GET" && url.pathname.startsWith("/outputs/")) {
    const target = path.normalize(path.join(ROOT, decodeURIComponent(url.pathname)));
    if (!target.startsWith(OUT + path.sep)) {
      res.writeHead(403);
      return res.end("Forbidden");
    }
    return serveFile(res, target, TYPES[path.extname(target)] || "application/octet-stream");
  }

  if (req.method === "GET" && url.pathname.startsWith("/backgrounds/")) {
    const filename = path.basename(decodeURIComponent(url.pathname));
    const target = path.join(BGS, filename);
    return serveFile(res, target, "image/gif");
  }

  if (req.method === "GET" && (url.pathname === "/" || url.pathname === "/index.html")) {
    const html = await readFile(path.join(PUBLIC, "index.html"));
    res.writeHead(200, { "Content-Type": "text/html" });
    return res.end(html);
  }

  res.writeHead(404);
  res.end("Not found");
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`Lofi generator running at http://localhost:${PORT}`);
});

