function setPrompt(text, mood) {
  $("prompt").value = text;
  if (mood) $("mood").value = mood;
}

function showTool() {
  const t = $("tool").value;
  $("promptFields").classList.toggle("hidden", t !== "lofi-prompt");
  $("ytFields").classList.toggle("hidden", t !== "lofi-youtube");
  $("slidesFields").classList.toggle("hidden", t !== "slides");
  $("trimFields").classList.toggle("hidden", t !== "trim");
  $("genRow").classList.toggle("hidden", t === "trim");
  $("go").textContent = t === "trim" ? "Trim Pauses" : "Generate Lofi Video";
}
$("tool").addEventListener("change", showTool);
showTool();

async function post(url, body) {
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || "Request failed");
  return data;
}

function showResult(data) {
  currentJob = data.id;
  $("player").src = data.url;
  $("playerBox").classList.remove("hidden");
  $("downloads").classList.remove("hidden");
  $("dlMp4").href = data.url;
  $("dlMp4").setAttribute("download", `lofi-${data.id}.mp4`);
  $("dlWav").href = data.audioUrl || `/outputs/${data.id}/audio.wav`;
  $("dlWav").setAttribute("download", `lofi-${data.id}.wav`);
  $("pubYt").disabled = false;
  $("pubIg").disabled = false;
  loadHistory();
}

function setStatus(text, kind = "info") {
  const s = $("status");
  s.textContent = text;
  s.className = `status active ${kind}`;
}

$("go").addEventListener("click", async () => {
  const tool = $("tool").value;
  const seconds = Number($("seconds").value);
  const watermark = $("watermark").value.trim();
  const aspectRatio = $("aspectRatio").value;
  const style = $("style").value;
  const mood = $("mood").value;
  const btn = $("go");

  btn.disabled = true;
  setStatus("Synthesizing audio and rendering video... please wait.", "info");

  try {
    let data;
    if (tool === "lofi-youtube") {
      data = await post("/api/from-youtube", {
        youtubeUrl: $("ytUrl").value.trim(),
        gifUrl: $("gifUrl").value.trim(),
        seconds,
        watermark,
        aspectRatio,
      });
      setStatus("Done! Rendered from YouTube audio.", "ok");
    } else if (tool === "slides") {
      const scenes = $("scenes").value.trim();
      if (!scenes) throw new Error("Enter at least one scene line.");
      data = await post("/api/slides", { scenes, seconds, watermark, aspectRatio });
      setStatus(`Done! Rendered story slides (${data.moodLabel}).`, "ok");
    } else if (tool === "trim") {
      if (!currentJob) throw new Error("Select or render a video first, then trim it.");
      data = await post("/api/trim-silence", { jobId: currentJob });
      setStatus(`Done! Removed ${data.removedSeconds.toFixed(1)}s of silence pauses.`, "ok");
    } else {
      const prompt = $("prompt").value.trim();
