      data = await post("/api/generate", { prompt, seconds, style, mood, aspectRatio, watermark });
      setStatus(`Done! Rendered with ${data.moodLabel} palette.`, "ok");
    }
    showResult(data);
  } catch (err) {
    setStatus("Error: " + err.message, "error");

