args.CodeContent:
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const REF_DIR = path.join(ROOT, "public", "reference_repo");
const LOFI_DIR = path.join(REF_DIR, "lofi");
const ANIME_DIR = path.join(REF_DIR, "anime");
const PIXAR_DIR = path.join(REF_DIR, "pixar");

fs.mkdirSync(LOFI_DIR, { recursive: true });
fs.mkdirSync(ANIME_DIR, { recursive: true });
fs.mkdirSync(PIXAR_DIR, { recursive: true });

async function getTree(owner, repo, branch = "main") {
  const res = await fetch(`https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`, {
    headers: { "User-Agent": "Node-Ref-Fetcher" },
  });
  const data = await res.json();
  if (!data.tree) throw new Error(`Failed to load tree for ${owner}/${repo}: ${data.message || "Unknown error"}`);
  return data.tree;
}

async function downloadFile(url, destPath) {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const res = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0" } });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const buf = Buffer.from(await res.arrayBuffer());
      if (buf.length < 5000) throw new Error(`File too small (${buf.length} bytes)`);
      fs.writeFileSync(destPath, buf);
      return buf.length;
    } catch (e) {
      if (attempt === 3) throw e;
      await new Promise((r) => setTimeout(r, 800));
    }
  }
}

async function poolExecute(tasks, concurrency = 6) {
  let index = 0;
  const results = [];
  async function worker() {
    while (index < tasks.length) {
      const cur = index++;
      try {
        const res = await tasks[cur]();
        results[cur] = { success: true, res };
      } catch (err) {
        results[cur] = { success: false, err: err.message };
      }
    }
  }
  const workers = Array.from({ length: concurrency }, () => worker());
  await Promise.all(workers);
  return results;
}

function cleanTitle(filename) {
  return filename
    .replace(/\.[^.]+$/, "")
    .replace(/[-_]+/g, " ")
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim();
}

async function main() {
  console.log("Fetching repository manifests from GitHub...");
  const [d3Tree, denverTree, orangciTree, joshuaTree] = await Promise.all([
    getTree("D3Ext", "Aesthetic-Wallpapers", "main"),
    getTree("DenverCoder1", "minimalistic-wallpaper-collection", "main"),
    getTree("orangci", "walls", "master"),
    getTree("JoshuaThadi", "Wall-E-Desk", "main"),
  ]);

  console.log("Selecting candidate sets...");
  // 1. ANIME: 100 images from JoshuaThadi (Anime & landscape-anime) + D3Ext
  const joshuaAnime = joshuaTree.filter(
    (f) => (f.path.startsWith("Anime/") || f.path.startsWith("landscape-anime/")) && /\.(jpg|png|webp|jpeg)/i.test(f.path)
  );
  const d3Anime = d3Tree.filter(
    (f) =>
      f.path.startsWith("images/") &&
      /japan|samurai|anime|manga|totoro|one-piece|naruto|ghibli|shougan|torii|sakura/i.test(f.path)
  );
  const animePool = [...joshuaAnime, ...d3Anime];

  // 2. LOFI: 100 images from D3Ext (lofi, cafe, room, rain, chill, cozy, night, pastel) + DenverCoder1 (Alena Aenami, calm)
  const d3Lofi = d3Tree.filter(
    (f) =>
      f.path.startsWith("images/") &&
      /lofi|cafe|room|cat|coffee|rain|chill|night|cozy|pastel|pixel|window|evening|sunset|train|van|camp|pond/i.test(
        f.path
      )
  );
  const denverLofi = denverTree.filter(
    (f) =>
      f.path.startsWith("images/") &&
      /aenami|calm|sunset|night|beach|camp|sky|dawn|horizon|quiet|clouds|landscape/i.test(f.path)
  );
  const lofiPool = [...d3Lofi, ...denverLofi];

  // 3. PIXAR / 3D: 100 images from orangci (3D models, CGI, astronaut, landscape renders) + D3Ext (3D renders, cute-town, cabin, puppy, neon)
  const orangci3D = orangciTree.filter(
    (f) =>
      !f.path.includes("/") &&
      /\.(jpg|png|webp|jpeg)/i.test(f.path) &&
      /3d|model|valley|astronaut|atlantis|village|landscape|cyber|cube|neon|space|planet|future|castle|crystal/i.test(
        f.path
      )
  );
  const d3Pixar = d3Tree.filter(
    (f) =>
      f.path.startsWith("images/") &&
      /cute-town|cabin|puppy|robot|cube|planets|crystals|earth|steampunk|orbit|fractal|shiny/i.test(f.path)
  );
  const denver3D = denverTree.filter(
    (f) => f.path.startsWith("images/") && /planet|scifi|space|future|minimal|city|building/i.test(f.path)
  );
  const pixarPool = [...orangci3D, ...d3Pixar, ...denver3D];

  console.log(`Pools gathered: Lofi=${lofiPool.length}, Anime=${animePool.length}, Pixar=${pixarPool.length}`);

  const catalog = [];
  const downloadTasks = [];

  // Prepare 100 LOFI
  const selectedLofi = lofiPool.slice(0, 100);
  selectedLofi.forEach((item, idx) => {
    const num = String(idx + 1).padStart(3, "0");
    const rawName = item.path.split("/").pop();
    const ext = path.extname(rawName).toLowerCase() || ".jpg";
    const filename = `lofi_${num}${ext}`;
    const dest = path.join(LOFI_DIR, filename);

    let rawUrl;
    if (item.path.startsWith("images/") && d3Lofi.includes(item)) {
      rawUrl = `https://raw.githubusercontent.com/D3Ext/Aesthetic-Wallpapers/main/${item.path}`;
    } else {
      rawUrl = `https://raw.githubusercontent.com/DenverCoder1/minimalistic-wallpaper-collection/main/${item.path}`;
    }

    catalog.push({
      id: `lofi_${num}`,
      title: cleanTitle(rawName) || `Lofi Scene #${num}`,
      category: "lofi",
      filename,
      path: `/reference_repo/lofi/${filename}`,
      style: "lofi",
      mood: idx % 3 === 0 ? "night" : idx % 3 === 1 ? "lofi_cafe" : "sunset",
      tags: ["lofi", "aesthetic", "cozy", "study"],
      source: "GitHub Aesthetic Collections",
    });

    downloadTasks.push(async () => {
      await downloadFile(rawUrl, dest);
    });
  });

  // Prepare 100 ANIME
  const selectedAnime = animePool.slice(0, 100);
  selectedAnime.forEach((item, idx) => {
    const num = String(idx + 1).padStart(3, "0");
    const rawName = item.path.split("/").pop();
    const ext = path.extname(rawName).toLowerCase() || ".jpg";
    const filename = `anime_${num}${ext}`;
    const dest = path.join(ANIME_DIR, filename);

    let rawUrl;
    if (joshuaAnime.includes(item)) {
      // JoshuaThadi repo paths have spaces and special chars, encodeURIComponent per segment
      const encodedPath = item.path.split("/").map(encodeURIComponent).join("/");
      rawUrl = `https://raw.githubusercontent.com/JoshuaThadi/Wall-E-Desk/main/${encodedPath}`;
    } else {
      rawUrl = `https://raw.githubusercontent.com/D3Ext/Aesthetic-Wallpapers/main/${item.path}`;
    }

    catalog.push({
      id: `anime_${num}`,
      title: cleanTitle(rawName) || `Anime Scene #${num}`,
      category: "anime",
      filename,
      path: `/reference_repo/anime/${filename}`,
      style: "anime",
      mood: idx % 3 === 0 ? "shinkai_anime" : idx % 3 === 1 ? "ghibli_garden" : "sunset",
      tags: ["anime", "cel", "shinkai", "ghibli", "vibrant"],
      source: "GitHub Anime Curations",
    });

    downloadTasks.push(async () => {
      await downloadFile(rawUrl, dest);
    });
  });

  // Prepare 100 PIXAR
  const selectedPixar = pixarPool.slice(0, 100);
  selectedPixar.forEach((item, idx) => {
    const num = String(idx + 1).padStart(3, "0");
    const rawName = item.path.split("/").pop();
    const ext = path.extname(rawName).toLowerCase() || ".jpg";
    const filename = `pixar_${num}${ext}`;
    const dest = path.join(PIXAR_DIR, filename);

    let rawUrl;
    if (orangci3D.includes(item)) {
      rawUrl = `https://raw.githubusercontent.com/orangci/walls/master/${encodeURIComponent(item.path)}`;
    } else if (d3Pixar.includes(item)) {
      rawUrl = `https://raw.githubusercontent.com/D3Ext/Aesthetic-Wallpapers/main/${item.path}`;
    } else {
      rawUrl = `https://raw.githubusercontent.com/DenverCoder1/minimalistic-wallpaper-collection/main/${item.path}`;
    }

    catalog.push({
      id: `pixar_${num}`,
      title: cleanTitle(rawName) || `Pixar 3D Scene #${num}`,
      category: "pixar",
      filename,
      path: `/reference_repo/pixar/${filename}`,
      style: "pixar",
      mood: idx % 3 === 0 ? "pixar_cozy" : idx % 3 === 1 ? "dreamy" : "morning",
      tags: ["pixar", "3d", "cgi", "bloom", "volumetric"],
      source: "GitHub 3D/CGI Render Curations",
    });

    downloadTasks.push(async () => {
      await downloadFile(rawUrl, dest);
    });
  });

  console.log(`Starting parallel download of ${downloadTasks.length} reference images (concurrency: 8)...`);
  const results = await poolExecute(downloadTasks, 8);
  const successCount = results.filter((r) => r.success).length;
  const failCount = results.filter((r) => !r.success).length;
  console.log(`Downloads finished! Success: ${successCount}, Failed: ${failCount}`);

  // Save catalog
  const catalogPath = path.join(REF_DIR, "catalog.json");
  fs.writeFileSync(catalogPath, JSON.stringify(catalog, null, 2));
  console.log(`Saved reference catalog to ${catalogPath} with ${catalog.length} indexed artworks.`);
}

main().catch(console.error);

