  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text-muted);
  border-radius: 9999px;
  padding: 0.35rem 0.85rem;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
