  background: var(--surface);
  border: 1px solid var(--border);
  color: var(--text);
  padding: 0.45rem 0.9rem;
  border-radius: 10px;
  font-size: 0.85rem;
  min-width: 240px;
  transition: all 0.2s ease;
}

