type SceneInfo = {
  id: string;
  label: string;
  tag: string;
  style?: string;
  url: string;
};

export type ReferenceItem = {
  id: string;
  title: string;
  category: "lofi" | "anime" | "pixar";
  filename: string;
  path: string;
  style: Style;
  mood: string;
  tags: string[];
  source: string;
};

type Result = {
  id: string;
  url: string;
  audioUrl?: string;
  moodLabel?: string;
  mood?: string;
  bgScene?: string;
  removedSeconds?: number;
  aspectRatio?: AspectRatio;
  title?: string;
  sub?: string;
  seconds?: number;
  createdAt?: number;
  size?: number;
  style?: string;
