useEffect(() => {
  fetch("/api/moods")
    .then((r) => r.json())
    .then((data) => {
      if (data.moods && Array.isArray(data.moods)) {
        setMoods(data.moods);
      }
    })
    .catch(() => {});

  fetch("/api/scenes")
    .then((r) => r.json())
    .then((data) => {
      if (data.scenes && Array.isArray(data.scenes)) {
        setScenesList(data.scenes);
      }
