  async function loadReferences() {
    try {
      const res = await fetch("/api/references?limit=300");
      const data = await res.json();
      if (!data.items || !data.items.length) return;

      const sceneSelect = $("scene");
      const lofiGroup = document.createElement("optgroup");
      lofiGroup.label = "🎧 Lofi Reference Repo (100 assets)";
      const animeGroup = document.createElement("optgroup");
      animeGroup.label = "🌸 Anime & Ghibli Reference Repo (100 assets)";
      const pixarGroup = document.createElement("optgroup");
      pixarGroup.label = "✨ Pixar 3D Reference Repo (100 assets)";

      for (const item of data.items) {
        const opt = document.createElement("option");
        opt.value = item.path;
        opt.textContent = `${item.title} [${item.style} • ${item.mood}]`;
        if (item.category === "lofi") lofiGroup.appendChild(opt);
        else if (item.category === "anime") animeGroup.appendChild(opt);
        else if (item.category === "pixar") pixarGroup.appendChild(opt);
      }

      sceneSelect.appendChild(lofiGroup);
      sceneSelect.appendChild(animeGroup);
      sceneSelect.appendChild(pixarGroup);
    } catch (err) {
      console.warn("Could not load references:", err);
    }
  }

  loadReferences();
  loadHistory();
</script>

